<script setup>
import { computed, onMounted, onUnmounted, ref } from 'vue'
import { useRoute } from 'vue-router'
import { articles } from '../content.js'
import { bookmarks, toggleBookmark, copyText } from '../state.js'
import Icon from '../components/Icon.vue'
const route = useRoute(); const article = computed(() => articles.find(a => a.id === route.params.id)); const progress = ref(0)
function update() { const el = document.querySelector('.article-body'); if (!el) return; const r = el.getBoundingClientRect(); progress.value = Math.min(100, Math.max(0, (window.innerHeight - r.top) / (r.height + window.innerHeight) * 100)) }
onMounted(() => { update(); window.addEventListener('scroll', update, { passive: true }); window.addEventListener('resize', update) })
onUnmounted(() => { window.removeEventListener('scroll', update); window.removeEventListener('resize', update) })
</script>
<template><div v-if="article" class="article-page container page-space"><div class="reading-progress" role="progressbar" aria-label="阅读进度" :aria-valuenow="Math.round(progress)" aria-valuemin="0" aria-valuemax="100"><span :style="{ width: `${progress}%` }"></span></div><RouterLink to="/journal" class="back-link">← 返回笔记</RouterLink><header class="article-heading"><div class="eyebrow">{{ article.category }} / JOURNAL</div><h1>{{ article.title }}</h1><p>{{ article.summary }}</p><div class="article-byline"><span>栖物里编辑 · {{ article.date }} · 约 {{ article.minutes }} 分钟</span><div><button class="icon-button" :aria-pressed="bookmarks.includes(article.id)" :aria-label="bookmarks.includes(article.id) ? '取消收藏' : '收藏这篇笔记'" @click="toggleBookmark(article.id)"><Icon name="bookmark" /></button><button class="icon-button" aria-label="复制文章链接" @click="copyText(`https://qiwuli.com/journal/${article.id}`)"><Icon name="copy" /></button></div></div></header><div class="article-layout"><article class="article-body prose"><section v-for="(section, i) in article.sections" :key="section.title" :id="`section-${i}`"><h2>{{ section.title }}</h2><p v-for="paragraph in section.paragraphs" :key="paragraph">{{ paragraph }}</p></section><div class="article-end"><Icon name="leaf" /><p>欢迎分享你的实践。</p><RouterLink to="/contact" class="text-link">聊聊你的想法 <Icon name="diagonal" /></RouterLink></div></article><aside class="toc"><span>这篇笔记里</span><a v-for="(section, i) in article.sections" :key="section.title" :href="`#section-${i}`">0{{ i + 1 }} · {{ section.title }}</a><small>收藏只保存在这台设备的浏览器中。</small></aside></div><section class="related"><h2>接着读一篇</h2><RouterLink v-for="next in articles.filter(a => a.id !== article.id)" :key="next.id" :to="`/journal/${next.id}`"><span>{{ next.title }}</span><Icon name="arrow" /></RouterLink></section></div></template>
